(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[829],{2601:(n,t,r)=>{"use strict";r.r(t),r.d(t,{default:()=>a});var o=r(7876),e=r(7328),d=r.n(e);let s=JSON.parse('{"r":"<h1>Технологический радар \xabБудущее 2.0\xbb</h1>\\n<p>Радар отражает текущие технологии, инструменты и архитектурные подходы компании (медикланика + финтех), а также предлагаемые изменения к целевой архитектуре (Task 1–2). Радар охватывает не только технологии, но и подходы: Data Mesh, Data Contracts, Data Governance, Strangler-вывод легаси.</p>\\n<h2>Кольца</h2>\\n<table>\\n<thead>\\n<tr>\\n<th>Кольцо</th>\\n<th>Значение</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><strong>Adopt</strong></td>\\n<td>Использовать как целевую технологию или стандарт</td>\\n</tr>\\n<tr>\\n<td><strong>Trial</strong></td>\\n<td>Внедрить и проверить на пилотных проектах</td>\\n</tr>\\n<tr>\\n<td><strong>Assess</strong></td>\\n<td>Изучить и оценить применимость</td>\\n</tr>\\n<tr>\\n<td><strong>Hold</strong></td>\\n<td>Не развивать, постепенно выводить из эксплуатации или ограничивать использование</td>\\n</tr>\\n</tbody></table>\\n<h2>Направления</h2>\\n<ol>\\n<li><strong>Платформа данных и хранение</strong> — хранение, организация и масштабирование данных.</li>\\n<li><strong>Интеграция и обработка данных</strong> — обмен данными между доменами, обработка и автоматизация потоков.</li>\\n<li><strong>Аналитика и бизнес-сервисы</strong> — аналитика, визуализация, самообслуживание и использование данных бизнес-пользователями.</li>\\n<li><strong>Безопасность и управление данными</strong> — защита информации, управление доступом, контроль качества и надёжность.</li>\\n</ol>\\n<h2>Бизнес-сценарии</h2>\\n<p>Каждая технология связана с бизнес-сценариями целевой архитектуры (Task 1):</p>\\n<ul>\\n<li><strong>S1</strong> — быстрая отчётность (минуты, а не часы)</li>\\n<li><strong>S2</strong> — самообслуживание бизнес-пользователей</li>\\n<li><strong>S3</strong> — независимое развитие финтеха</li>\\n<li><strong>S4</strong> — ИИ-диагностика</li>\\n<li><strong>S5</strong> — подключение нового домена / партнёра</li>\\n<li><strong>S6</strong> — единые KPI</li>\\n<li><strong>Q</strong> — качество и комплаенс медицинских и финансовых сервисов</li>\\n</ul>\\n<p>Теги сценариев S1–S6 и Q можно использовать для фильтрации каталога на главной странице. Позиции в кольце <strong>Hold</strong> помечены сценариями, которые они <em>блокируют</em>.</p>\\n<h2>Как устроен радар</h2>\\n<p>Радар собран на open-source статическом генераторе <a target=\\"_blank\\" rel=\\"noopener noreferrer\\" href=\\"https://github.com/AOEpeople/aoe_technology_radar\\">aoe_technology_radar</a> (AOE GmbH). Позиции — Markdown-файлы в папке <code>radar/&lt;дата выпуска&gt;/</code> (текущий выпуск — <code>2026-11-10</code>); конфигурация — <code>config.json</code>, текст этой страницы — <code>about.md</code>.</p>\\n<p>Пересборка статического сайта: <code>npm run build</code> в папке <code>tech_radar/</code> (результат — <code>tech_radar/build/</code>), локальный просмотр: <code>npm run serve</code>.</p>\\n"}');var l=r(1945);let a=()=>(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(d(),{children:(0,o.jsx)("title",{children:(0,l.Ef)("Help and About")})}),(0,o.jsx)("div",{dangerouslySetInnerHTML:{__html:s.r}})]})},4820:(n,t,r)=>{(window.__NEXT_P=window.__NEXT_P||[]).push(["/help-and-about-tech-radar",function(){return r(2601)}])}},n=>{var t=t=>n(n.s=t);n.O(0,[636,593,792],()=>t(4820)),_N_E=n.O()}]);